/* options.js — configuration UI + native bridge diagnostics + fixture test. */
"use strict";

const $ = (sel) => document.querySelector(sel);
const SETTINGS_KEY = "settings";

/* 8x8 red PNG, generated by tools/make_icons.py's sibling snippet — see
 * tests/js/fixture_png.b64 (identical bytes). Used to verify the whole
 * save pipeline byte-for-byte. */
const FIXTURE_PNG_B64 =
  "iVBORw0KGgoAAAANSUhEUgAAAAgAAAAICAIAAABLbSncAAAAEUlEQVR42mM4o+SCFTEMLQkABopMgbu286wAAAAASUVORK5CYII=";
const FIXTURE_SHA256 =
  "de386e82a5d9823effcfab4140cd71f347d817dac5439858e21023e6caf63a14";

function sendHost(command) {
  return chrome.runtime.sendMessage({ type: "host", command });
}

function setStatus(el, text, cls) {
  el.textContent = text;
  el.className = "statusline " + (cls || "");
}

async function refreshHostStatus() {
  const el = $("#hostStatus");
  const reply = await sendHost({ type: "health_check" });
  if (reply && reply.status === "ok") {
    setStatus(el, `connected — host v${reply.version}, protocol v` +
      `${reply.protocol_version}, ` +
      (reply.output_dir_configured ? "output folder configured"
                                   : "output folder NOT configured"),
      "ok");
    const st = await sendHost({ type: "get_status" });
    if (st && st.status === "ok") {
      $("#outputDir").textContent = st.output_dir || "(not set)";
    }
  } else {
    const why = reply ? `${reply.code}: ${reply.message}` : "no response";
    setStatus(el, `not connected — ${why}. Install the native host and ` +
      "restart Chrome (see README).", "err");
    $("#outputDir").textContent = "—";
  }
}

$("#chooseFolder").addEventListener("click", async () => {
  const btn = $("#chooseFolder");
  btn.disabled = true;
  try {
    const reply = await sendHost({ type: "choose_output_folder" });
    if (reply && reply.status === "ok" && !reply.cancelled) {
      $("#outputDir").textContent = reply.output_dir;
      setStatus($("#hostStatus"), "output folder updated", "ok");
    } else if (reply && reply.cancelled) {
      setStatus($("#hostStatus"), "folder selection cancelled");
    } else if (reply && reply.status === "error") {
      setStatus($("#hostStatus"), `${reply.code}: ${reply.message}`, "err");
    }
  } finally {
    btn.disabled = false;
  }
});

$("#testSave").addEventListener("click", async () => {
  const el = $("#testResult");
  const btn = $("#testSave");
  btn.disabled = true;
  setStatus(el, "saving fixture…");
  try {
    const reply = await sendHost({
      type: "save_original",
      filename: "ttstk-fixture.png",
      data_base64: FIXTURE_PNG_B64,
      media_type: "image/png",
      sha256: FIXTURE_SHA256,
      overwrite: true,
    });
    if (reply && reply.status === "ok") {
      // The host only returns "ok" after re-verifying the sha256 of the exact
      // bytes it decoded, and it fsyncs before the atomic rename, so an "ok"
      // here means the file on disk matches the fixture byte-for-byte.
      setStatus(el, `verified: ${reply.path} (${reply.bytes_written} bytes, ` +
        `sha256 ${reply.sha256.slice(0, 12)}…)`, "ok");
    } else if (reply && reply.status === "error") {
      setStatus(el, `${reply.code}: ${reply.message}`, "err");
    } else {
      setStatus(el, "host unreachable — is it installed? (see README)", "err");
    }
  } finally {
    btn.disabled = false;
  }
});

async function loadSettings() {
  const stored = await chrome.storage.local.get(SETTINGS_KEY);
  const s = stored[SETTINGS_KEY] || {};
  $("#namingMode").value = s.namingMode || "suggested";
  $("#namingPrefix").value = s.namingPrefix ?? "sticker_";
  $("#fetchGapMs").value = s.fetchGapMs ?? 300;
  $("#patterns").value = (s.patterns ||
    ["tiktok-dm-sticker", "sticker-sign", "video2sticker",
     "sticker-set-frame", "photo-comment", "tos-alisg", "tplv-dhq",
     "tplv-gi79"]).join("\n");
  $("#suffixes").value = (s.suffixes ||
    ["tiktok.com", "tiktokcdn.com", "tiktokcdn-us.com", "tiktokcdn-eu.com",
     "tiktokv.com", "ibyteimg.com", "byteimg.com", "ttwstatic.com"]).join("\n");
}

$("#saveSettings").addEventListener("click", async () => {
  const msg = $("#saveMsg");
  const patterns = $("#patterns").value.split("\n")
    .map((s) => s.trim()).filter(Boolean);
  const suffixes = $("#suffixes").value.split("\n")
    .map((s) => s.trim()).filter(Boolean);
  if (!patterns.length || !suffixes.length) {
    msg.textContent = "patterns and hosts must not be empty";
    return;
  }
  await chrome.storage.local.set({
    [SETTINGS_KEY]: {
      patterns,
      suffixes,
      namingMode: $("#namingMode").value,
      namingPrefix: $("#namingPrefix").value.trim() || "sticker_",
      fetchGapMs: Math.max(0, Math.min(5000,
        parseInt($("#fetchGapMs").value, 10) || 0)),
    },
  });
  msg.textContent = "saved ✓";
  setTimeout(() => { msg.textContent = ""; }, 2500);
});

loadSettings();
refreshHostStatus();
